import test from 'node:test';
import assert from 'node:assert/strict';
import { recordPayment, balanceDue } from '../src/payments.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';

test('balanceDue for issued invoice with no payments', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const balance = balanceDue(issued.value);
  // 1 × €95.00 + 21% VAT = €114.95
  assert.equal(balance, 11495);
});

test('balanceDue with payments', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const invoice = {
    ...issued.value,
    payments: [
      { amount: 5000, date: '2026-10-08' },
      { amount: 3000, date: '2026-10-09' },
    ],
  };

  const balance = balanceDue(invoice);
  // Total: €114.95, Paid: €80.00, Due: €34.95
  assert.equal(balance, 3495);
});

test('balanceDue for fully paid invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const invoice = {
    ...issued.value,
    payments: [{ amount: 6050, date: '2026-10-08' }],
  };

  const balance = balanceDue(invoice);
  // 100 × €0.50 + 21% VAT = €60.50
  assert.equal(balance, 0);
});

test('recordPayment on issued invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const paymentResult = recordPayment(issued.value, {
    amount: 5000,
    date: '2026-10-08',
  });

  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'partially_paid');
  assert.equal(paymentResult.value.payments.length, 1);
  assert.equal(paymentResult.value.payments[0].amount, 5000);
  assert.equal(paymentResult.value.payments[0].date, '2026-10-08');
});

test('recordPayment transitions to paid', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const paymentResult = recordPayment(issued.value, {
    amount: 6050,
    date: '2026-10-08',
  });

  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'paid');
});

test('recordPayment multiple times', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const payment1 = recordPayment(issued.value, {
    amount: 5000,
    date: '2026-10-08',
  });

  assert.equal(payment1.ok, true);
  assert.equal(payment1.value.status, 'partially_paid');

  const payment2 = recordPayment(payment1.value, {
    amount: 6495,
    date: '2026-10-09',
  });

  assert.equal(payment2.ok, true);
  assert.equal(payment2.value.status, 'paid');
  assert.equal(payment2.value.payments.length, 2);
});

test('recordPayment fails with NOT_ISSUED on draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);

  const paymentResult = recordPayment(result.value, {
    amount: 5000,
    date: '2026-10-08',
  });

  assert.equal(paymentResult.ok, false);
  assert.equal(paymentResult.error, 'NOT_ISSUED');
});

test('recordPayment fails with AMOUNT_INVALID for non-integer', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const paymentResult = recordPayment(issued.value, {
    amount: 5000.5,
    date: '2026-10-08',
  });

  assert.equal(paymentResult.ok, false);
  assert.equal(paymentResult.error, 'AMOUNT_INVALID');
});

test('recordPayment fails with AMOUNT_INVALID for negative amount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const paymentResult = recordPayment(issued.value, {
    amount: -5000,
    date: '2026-10-08',
  });

  assert.equal(paymentResult.ok, false);
  assert.equal(paymentResult.error, 'AMOUNT_INVALID');
});

test('recordPayment fails with AMOUNT_INVALID for zero', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const paymentResult = recordPayment(issued.value, {
    amount: 0,
    date: '2026-10-08',
  });

  assert.equal(paymentResult.ok, false);
  assert.equal(paymentResult.error, 'AMOUNT_INVALID');
});

test('recordPayment fails with OVERPAYMENT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const paymentResult = recordPayment(issued.value, {
    amount: 20000,
    date: '2026-10-08',
  });

  assert.equal(paymentResult.ok, false);
  assert.equal(paymentResult.error, 'OVERPAYMENT');
});

test('recordPayment does not mutate input invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const invoice = issued.value;

  recordPayment(invoice, {
    amount: 5000,
    date: '2026-10-08',
  });

  assert.equal(invoice.payments, undefined);
  assert.equal(invoice.status, 'issued');
});

test('recordPayment creates payments array if missing', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const paymentResult = recordPayment(issued.value, {
    amount: 5000,
    date: '2026-10-08',
  });

  assert.equal(paymentResult.ok, true);
  assert(Array.isArray(paymentResult.value.payments));
  assert.equal(paymentResult.value.payments.length, 1);
});

test('recordPayment on partially paid invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const payment1 = recordPayment(issued.value, {
    amount: 5000,
    date: '2026-10-08',
  });

  assert.equal(payment1.ok, true);
  assert.equal(payment1.value.status, 'partially_paid');

  const payment2 = recordPayment(payment1.value, {
    amount: 3000,
    date: '2026-10-09',
  });

  assert.equal(payment2.ok, true);
  assert.equal(payment2.value.status, 'partially_paid');
  assert.equal(payment2.value.payments.length, 2);
});

test('balanceDue returns 0 for overpaid invoice', () => {
  const invoice = {
    status: 'paid',
    payments: [{ amount: 10000, date: '2026-10-08' }],
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1, unitPrice: 50, name: 'Sticker sheet', vatRate: 21, discountPercent: 0 }],
  };

  const balance = balanceDue(invoice);
  assert.equal(balance, 0);
});

test('recordPayment with exact payment amount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const due = balanceDue(issued.value);
  const paymentResult = recordPayment(issued.value, {
    amount: due,
    date: '2026-10-08',
  });

  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'paid');
  assert.equal(balanceDue(paymentResult.value), 0);
});

